module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);
    const engine = require("../../runtime/ivr-engine").getInstance(RED);

    function WaitResponseNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        engine.registerWaitingNode(node);

        node.on('input', async function(msg) {
            const sessionId = msg.sessionId;
            if (!sessionId) {
                node.error("No sessionId");
                return;
            }

            await sessionManager.setWaitingNode(sessionId, node.id, {
                timeout: config.timeout,
                allowed: config.allowedResponses
            });

            node.status({ fill: "blue", shape: "dot", text: "Waiting..." });
            // Do not send anything yet — flow pauses here
        });

        // Called by engine when callback arrives
        node.onResponse = function(msg) {
            node.status({ fill: "green", shape: "dot", text: msg.dtmfDigits });
            node.send(msg);
        };
    }

    RED.nodes.registerType("wait-response", WaitResponseNode);
};